<template>
  <div id="booking">
    <v-carousel height="100vh" hide-controls dark hide-delimiters class="myCarousel">
      <v-carousel-item
        v-for="(item,i) in carouselitems"
        :key="i"
        :src="item.src"
        class="carouselItem"
      ></v-carousel-item>
      <v-jumbotron dark class="myJumbotron">
        <v-container fill-height>
          <v-layout align-center>
            <v-flex class="showcaseText">
              <h2
                class="text-lg-center text-md-center text-xs-center myHeading wow fadeInUp"
              >Booking</h2>
              <p
                class="subheading text-lg-center text-md-center text-xs-center mygreenText wow fadeInRight"
              >Hospitality Unparalled</p>
            </v-flex>
          </v-layout>
        </v-container>
      </v-jumbotron>
    </v-carousel>
    <v-layout class="section" row wrap>
      <v-flex lg12 md12 sm12 xs12>
        <v-card class="form-card" justify-center>
          <v-card-text class="text-lg-center text-md-center text-sm-center">Book with us</v-card-text>
          <div class="form-body">
            <form>
              <v-text-field v-model="Name" :rules="nameRules" :counter="30" label="Name" required></v-text-field>
              <v-text-field v-model="number" :counter="10" label="Phone Number" required></v-text-field>
              <v-text-field
                v-model="Email"
                :counter="50"
                :rules="emailRules"
                label="E-mail"
                required
              ></v-text-field>
              <!-- <v-select
                v-model="services"
                :items="Services"
                :error-messages="selectErrors"
                label="Services"
              ></v-select>-->
              <v-layout row wrap>
                <v-flex lg8>
                  <v-select v-model="accomodation" :items="Accomodation" label="Accomodations"></v-select>
                </v-flex>
                <v-flex lg4>
                  <v-text-field v-model="accnumber" label="Number of people" required></v-text-field>
                </v-flex>
              </v-layout>
              <v-layout row wrap>
                <v-flex lg8>
                  <v-select v-model="conference" :items="Conferences" label="Conference"></v-select>
                </v-flex>
                <v-flex lg4>
                  <v-text-field v-model="confnumber" label="Number of people" required></v-text-field>
                </v-flex>
              </v-layout>
              <v-layout row wrap>
                <v-flex xs12 sm6 md4>
                  <v-dialog
                    ref="dialog"
                    v-model="modal"
                    :return-value.sync="date"
                    persistent
                    lazy
                    full-width
                    width="290px"
                  >
                    <template v-slot:activator="{ on }">
                      <v-text-field
                        v-model="date"
                        label="Arrival Date"
                        prepend-icon="event"
                        readonly
                        v-on="on"
                      ></v-text-field>
                    </template>
                    <v-date-picker v-model="date" scrollable>
                      <v-spacer></v-spacer>
                      <v-btn flat color="brown" @click="modal = false">Cancel</v-btn>
                      <v-btn flat color="green" @click="$refs.dialog.save(date)">OK</v-btn>
                    </v-date-picker>
                  </v-dialog>
                </v-flex>
                <v-spacer></v-spacer>
                <v-flex xs12 sm6 md4></v-flex>
                <v-flex xs12 sm6 md4>
                  <v-dialog
                    ref="dialog"
                    v-model="modal2"
                    :return-value.sync="date"
                    persistent
                    lazy
                    full-width
                    width="290px"
                  >
                    <template v-slot:activator="{ on }">
                      <v-text-field
                        v-model="deptdate"
                        label="Departure Date"
                        prepend-icon="event"
                        readonly
                        v-on="on"
                      ></v-text-field>
                    </template>
                    <v-date-picker v-model="deptdate" scrollable>
                      <v-spacer></v-spacer>
                      <v-btn flat color="brown" @click="modal2 = false">Cancel</v-btn>
                      <v-btn flat color="green" @click="$refs.dialog.save(deptdate)">OK</v-btn>
                    </v-date-picker>
                  </v-dialog>
                </v-flex>
                <v-spacer></v-spacer>
              </v-layout>
              <!-- <v-checkbox
                v-model="checkbox"
                :error-messages="checkboxErrors"
                label="Free WiFI"
                required
                @change="$v.checkbox.$touch()"
                @blur="$v.checkbox.$touch()"
              ></v-checkbox>-->
              <v-layout row wrap justify-space-around>
                <v-btn color="#2cc804" @click="submit">submit</v-btn>
                <v-btn color="#531503" @click="clear">clear</v-btn>
              </v-layout>
            </form>
          </div>
        </v-card>
      </v-flex>
      <v-flex lg12 md12 sm12 xs12>
        <v-layout row wrap>
          <v-flex lg6>
            <div class="imageGrid">
              <v-container fluid>
                <div class="mapouter">
                  <div class="gmap_canvas">
                    <iframe
                      width="600"
                      height="500"
                      id="gmap_canvas"
                      src="https://maps.google.com/maps?q=fort%20hotel%20mami&t=&z=13&ie=UTF8&iwloc=&output=embed"
                      frameborder="0"
                      scrolling="no"
                      marginheight="0"
                      marginwidth="0"
                    ></iframe>Google Maps Generator by
                    <a
                      href="https://www.embedgooglemap.net"
                    >embedgooglemap.net</a>
                  </div>
                </div>
              </v-container>
            </div>
          </v-flex>
          <v-flex lg6>
            <div class="myfootertext textPosition">
              <h3 class="mybrowntext">Where to find us</h3>
              <p
                class="mybrownText"
              >The facility is located Approx. 50 meters from the Junction Mall, Family Bank branch, off Wote/Makindu road</p>
              <h3 class="mybrowntext">Contact us</h3>
              <p class="mybrownText">Tel: 0 412 244 000 213 | 0743518086</p>
              <p class="mybrownText">Email: forthotel@gmail.com</p>
              <p class="mybrownText">P.O Box 387-90300</p>
            </div>
          </v-flex>
        </v-layout>
      </v-flex>
    </v-layout>
  </div>
</template>
<script>
// import { validationMixin } from "vuelidate";
// import { required, maxLength, email } from "vuelidate/lib/validators";
import { APIService } from "../Api";
const apiService = new APIService();

export default {
  name: "Booking",
  // mixins: [validationMixin],

  // validations: {
  //   name: { required, maxLength: maxLength(10) },
  //   email: { required, email }
  //   // select: {},
  //   // checkbox: {
  //   //   checked(val) {
  //   //     return val;
  //   //   }
  //   // }
  // },

  data: () => ({
    name: "",
    number: "",
    email: "",
    // service: null,
    accomodation: null,
    conference: null,
    accnumber: "",
    confnumber: "",
    // Services: ["Accomodation", "Conferences"],
    Accomodation: [
      "Single Room",
      "Deluxe Rooms",
      "Family Rooms",
      "Suite",
      "None"
    ],
    Conferences: ["Mami BoardRoom", "Baraza Hall"],
    // checkbox: false,
    date: new Date().toISOString().substr(0, 10),
    deptdate: new Date().toISOString().substr(0, 10),
    modal: false,
    modal2: false,
    nameRules: [
      v => !!v || "Name is required",
      v => v.length <= 10 || "Name must be less than 10 characters"
    ],
    emailRules: [
      v => !!v || "E-mail is required",
      v => /.+@.+/.test(v) || "E-mail must be valid"
    ],
    carouselitems: [
      {
        src: require("../assets/images/grounds/imageY.jpg")
      },
      {
        src: require("../assets/images/grounds/imageG.jpg")
      },
      {
        src: require("../assets/images/grounds/imageO.jpg")
      }
    ]
  }),

  computed: {
    // checkboxErrors() {
    //   const errors = [];
    //   if (!this.$v.checkbox.$dirty) return errors;
    //   !this.$v.checkbox.checked && errors.push("You must agree to continue!");
    //   return errors;
    // },
    // selectErrors() {
    //   const errors = [];
    //   if (!this.$v.select.$dirty) return errors;
    //   !this.$v.select.required && errors.push("Item is required");
    //   return errors;
    // },
    // nameErrors() {
    //   const errors = [];
    //   if (!this.$v.name.$dirty) return errors;
    //   !this.$v.name.maxLength &&
    //     errors.push("Name must be at most 10 characters long");
    //   !this.$v.name.required && errors.push("Name is required.");
    //   return errors;
    // },
    // emailErrors() {
    //   const errors = [];
    //   if (!this.$v.email.$dirty) return errors;
    //   !this.$v.email.email && errors.push("Must be valid e-mail");
    //   !this.$v.email.required && errors.push("E-mail is required");
    //   return errors;
    // }
  },

  methods: {
    clear() {
      this.$v.$reset();
      this.name = "";
      this.email = "";
      this.service = null;
      this.accomodation = null;
      this.conference = null;
      this.checkbox = false;
    },
    submit() {
      let mail_subject = "Message From: " + this.name + " email: " + this.email;
      let mail_body =
        "Booking: " +
        "Accomodation: " +
        this.accomodation +
        "Conference: " +
        this.conference +
        " Number of people accomodation: " +
        this.accnumber +
        " Number of people conference: " +
        this.confnumber +
        " Arrival Date: " +
        this.date +
        " Departure Date: " +
        this.deptdate;

      apiService.sendFormData(mail_subject, mail_body);
      this.clear();
    }
  }
};
</script>
<style>
@import "../assets/css/style.css";
.form-card {
  margin-top: 2em;
}
.form-body {
  width: 60%;
  margin: 1em auto;
}

.mapouter {
  position: relative;
  text-align: right;
  height: 500px;
  width: 600px;
}
.gmap_canvas {
  overflow: hidden;
  background: none !important;
  height: 500px;
  width: 600px;
}
.myfootertext {
  padding-left: 3.5em;
}
@media screen and (max-width: 960px) {
  .mapouter {
    position: relative;
    text-align: right;
    height: 500px;
    width: 80vw;
  }
  .gmap_canvas {
    overflow: hidden;
    background: none !important;
    height: 500px;
    width: 80vw;
  }
}
</style>
